import {SchoolAccountsView,SavedAccountPicker} from '../../src/features/school-accounts.ts';
import type {SavedSchoolAccount,SchoolSystem} from '../../src/domain/school-accounts.ts';
export function createAccountFixture(){
 let rows:SavedSchoolAccount[]=[{id:crypto.randomUUID(),system:'course',account:'12345678',label:'选课测试',locked:false},{id:crypto.randomUUID(),system:'report',account:'87654321',label:'<img src=x onerror="alert(1)">',locked:false},{id:crypto.randomUUID(),system:'course',account:'',label:'无法解密的账号',locked:true}];
 let answer=true,fail=false,saves=0,removed=0,resets=0,loginCalls:{id:string;account:string;system:SchoolSystem}[]=[];
 const port={list:async()=>structuredClone(rows),save:async(value:{system:SchoolSystem;account:string;password:string;label:string;id?:string;confirmed:boolean})=>{if(!value.confirmed)throw Error('缺少确认');if(fail)throw Error('模拟保存失败');saves++;const id=value.id||crypto.randomUUID(),row={id,system:value.system,account:value.account,label:value.label,locked:false};const index=rows.findIndex(r=>r.id===id);if(index<0)rows.push(row);else rows[index]=row;return {id};},remove:async(id:string,confirmed:boolean)=>{if(!confirmed)throw Error('缺少确认');removed++;rows=rows.filter(r=>r.id!==id);},reset:async(confirmed:boolean)=>{if(!confirmed)throw Error('缺少确认');resets++;rows=[];}};
 const manager=new SchoolAccountsView(port,async()=>answer,()=>{}),picker=new SavedAccountPicker(port,'course',async account=>{loginCalls.push({id:account.id,account:account.account,system:account.system});},()=>{});
 manager.mount(document.querySelector('#account-host')!);picker.mount(document.querySelector('#picker-host')!);
  return {manager,picker,state:()=>({rows,saves,removed,resets,loginCalls,status:document.querySelector('[data-account-status]')?.textContent,busy:manager.isSaving}),confirm:(value:boolean)=>{answer=value;},fail:(value:boolean)=>{fail=value;},reopen:()=>manager.mount(document.querySelector('#account-host')!),reloadPicker:()=>picker.mount(document.querySelector('#picker-host')!),leave:()=>manager.leave(),longList:()=>{rows=Array.from({length:50},(_,i)=>({id:crypto.randomUUID(),system:i%2?'course':'report',account:'123456'+i,label:'长备注测试'.repeat(6),locked:false}));manager.mount(document.querySelector('#account-host')!);}};
}
